(43, 1, '2025-05-20 17:50:17', '2025-05-20 15:50:17', '{\n    \"nav_menus_created_posts\": {\n        \"value\": [\n            42\n        ],\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-05-20 15:50:17\"\n    },\n    \"nav_menu_item[-4960081050734583000]\": {\n        \"value\": {\n            \"object_id\": 42,\n            \"object\": \"page\",\n            \"menu_item_parent\": 0,\n            \"position\": 4,\n            \"type\": \"post_type\",\n            \"title\": \"Iniciar Sesion\",\n            \"url\": \"http://localhost/PW_wordpress/wordpress/?page_id=42\",\n            \"target\": \"\",\n            \"attr_title\": \"\",\n            \"description\": \"\",\n            \"classes\": \"\",\n            \"xfn\": \"\",\n            \"status\": \"publish\",\n            \"original_title\": \"Iniciar Sesion\",\n            \"nav_menu_term_id\": 3,\n            \"_invalid\": false,\n            \"type_label\": \"P\\u00e1gina\"\n        },\n        \"type\": \"nav_menu_item\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2025-05-20 15:50:17\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '944460ea-5345-46eb-9838-53af67a7a2a7', '', '', '2025-05-20 17:50:17', '2025-05-20 15:50:17', '', 0, 'http://localhost/PW_wordpress/wordpress/2025/05/20/944460ea-5345-46eb-9838-53af67a7a2a7/', 0, 'customize_changeset', '', 0),
